class DateConverter:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    @classmethod
    def from_dash_string(cls, date_str: str):
        # Factory constructor: Alternative initializer
        y, m, d = map(int, date_str.split('-'))
        return cls(y, m, d)

    @staticmethod
    def is_valid_year(year: int) -> bool:
        return 1900 <= year <= 2100

d = DateConverter.from_dash_string('2026-11-15')
print(f'{d.year}/{d.month}/{d.day}')
print('Valid year:', DateConverter.is_valid_year(2026))

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __repr__(self):
        return f'Vector({self.x}, {self.y})'

v1 = Vector(2, 4)
v2 = Vector(3, 1)
print(v1 + v2)  # Vector(5, 5)

class Temperature:
    def __init__(self, celsius: float):
        self._celsius = celsius

    @property
    def fahrenheit(self) -> float:
        return (self._celsius * 9/5) + 32

    @fahrenheit.setter
    def fahrenheit(self, value: float):
        self._celsius = (value - 32) * 5/9

t = Temperature(25)
print('In Fahrenheit:', t.fahrenheit)  # 77.0
t.fahrenheit = 212
print('In Celsius:', t._celsius)       # 100.0

