def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError as err:
        print('Error caught:', err)
        return None
    else:
        print('Division successful!')
        return result
    finally:
        print('Execution finished.')

print(safe_divide(10, 2))
print(safe_divide(10, 0))

class InvalidAgeError(Exception):
    """Raised when an age value is outside logical bounds."""
    def __init__(self, age: int, message: str = 'Age must be between 0 and 120'):
        self.age = age
        super().__init__(f'{message} (got {age})')

def register_voter(age: int):
    if age < 18 or age > 120:
        raise InvalidAgeError(age)
    return 'Voter registered!'

try:
    register_voter(150)
except InvalidAgeError as e:
    print('Custom caught:', e)

from contextlib import contextmanager

# Custom context manager using contextlib generator
@contextmanager
def transaction_scope(db_name: str):
    print(f'Starting transaction on {db_name}...')
    try:
        yield
        print('Committing transaction!')
    except Exception as e:
        print(f'Rolling back transaction due to {e}!')
        raise

with transaction_scope('users_db'):
    print('Modifying user records...')

