from functools import lru_cache
import itertools

# Memoized recursive Fibonacci with lru_cache
@lru_cache(maxsize=128)
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print('Fib(35):', fib(35))

